tbody tr:hover{ background:#f5f9ff; }
tbody tr.sel{ background:#eaf2ff; }

.btn-eye{
  background:var(--primary); color:#fff; border:none; padding:6px 8px;
  border-radius:calc(var(--radius) - 4px); cursor:pointer;
}
.btn-eye:hover{ filter:brightness(0.93); }

